/// <summary>
/// CB705 /04/09/2024 This class will swap credit and debit account code
/// </summary>
public class METSwapJournalAccountCode
{
}

Method.Source:
/// <summary>
///  This method will swap credit and debit account code
/// </summary>
/// <param name = "_journalNum">_journalNum</param>
public static void swapAccountCode(LedgerJournalId _journalNum)
{
    LedgerJournalTrans ledgerJournalTransCurDebit,ledgerJournalTransCurCredit, ledgerJournalTransUpd;

    select firstonly ledgerJournalTransCurDebit
        where ledgerJournalTransCurDebit.JournalNum == _journalNum
        && ledgerJournalTransCurDebit.AmountCurDebit;

    select firstonly ledgerJournalTransCurCredit
        where ledgerJournalTransCurCredit.JournalNum == _journalNum
        && ledgerJournalTransCurCredit.AmountCurCredit;
    ttsbegin;
    while select forupdate ledgerJournalTransUpd where
        ledgerJournalTransUpd.JournalNum == _journalNum
    {
        if (ledgerJournalTransUpd.AmountCurCredit)
        {
            ledgerJournalTransUpd.AccountType     = ledgerJournalTransCurDebit.AccountType;
            ledgerJournalTransUpd.LedgerDimension = ledgerJournalTransCurDebit.LedgerDimension;
        }
        if (ledgerJournalTransUpd.AmountCurDebit)
        {
            ledgerJournalTransUpd.AccountType     = ledgerJournalTransCurCredit.AccountType;
            ledgerJournalTransUpd.LedgerDimension = ledgerJournalTransCurCredit.LedgerDimension;
        }
        ledgerJournalTransUpd.update();
    }
    ttscommit;
}
